/* Per-firmware delta table (see bridge.h). deltas.h and deltas.S are generated by
 * tools/build_deltas.js and copied in by build.sh. */
#include "bridge.h"
#include "deltas.h"
#include "util.h"

static const struct {
  unsigned fw;
  const uint8_t *start, *end;
  const char *hubmods;
} wh_deltas[] = { WH_DELTA_TABLE };

const char wh_bridge_fws[] = WH_DELTA_FWS;

const struct wh_bridge *wh_bridge_for_fw(uint32_t fw){
  static struct wh_bridge b;
  for (size_t i = 0; i < sizeof wh_deltas / sizeof wh_deltas[0]; i++) {
    if (wh_deltas[i].fw != (fw >> 16)) continue;
    const uint8_t *d = wh_deltas[i].start;
    size_t n = (size_t)(wh_deltas[i].end - d);
    /* delta header (tools/make_delta.js): [16] op count, [56] rebuilt bridge size */
    uint64_t ops = n >= 96 ? get64(d + 16) : 0;
    size_t blen = n >= 96 ? (size_t)get64(d + 56) : 0;
    if (n < 96 || blen < 0x100000 || 96 + ops * 16 > n) {
      LOG("embedded delta for %x.%02x is corrupt (%zuB)\n", wh_deltas[i].fw >> 8, wh_deltas[i].fw & 0xff, n);
      return 0;
    }
    b = (struct wh_bridge){ wh_deltas[i].fw, d, n, blen, fnv1a64(d, n), wh_deltas[i].hubmods };
    return &b;
  }
  return 0;
}
